param(
  [switch]$WithHelpTags
)

$ErrorActionPreference = 'Stop'

if (-not (Get-Command nvim -ErrorAction SilentlyContinue)) {
  throw "Neovim ('nvim') is required to run this smoke check."
}

$nvimArgs = @(
  '--headless',
  '-u',
  'NONE',
  '+set rtp+=.',
  '+runtime plugin/gh-pr.lua',
  '+lua require("gh-pr").setup({ ui = { use_neotree = false, telescope_fallback = false }, diff_view = { prefetch = { enabled = true, concurrency = 2, text_extensions = { "lua", ".md" } }, non_text = { enabled = true, auto_preview = true, show_metadata = true } } })',
  '+lua local cfg = require("gh-pr.config").get(); local prefetch = cfg.diff_view.prefetch or {}; local comments_panel = cfg.diff_view.comments_panel or {}; local non_text = cfg.diff_view.non_text or {}; local pr_service = require("gh-pr.pr_service"); local virtual_files = require("gh-pr.virtual_files"); local actions = require("gh-pr.actions"); local ok_annotations = pcall(require, "gh-pr.check_annotations"); local ok_security_annotations = pcall(require, "gh-pr.security_annotations"); local ok_security_section = pcall(require, "gh-pr.neotree.review_sections.security"); assert(vim.fn.exists(":GhPrOpen") == 2, "Missing :GhPrOpen command"); assert(vim.fn.exists(":GhPrReviewRefresh") == 2, "Missing :GhPrReviewRefresh command"); assert(vim.fn.exists(":GhPRReviewRefresh") == 2, "Missing :GhPRReviewRefresh alias"); assert(vim.fn.maparg("<Plug>(gh-pr-open)", "n") ~= "", "Missing <Plug>(gh-pr-open)"); assert(vim.fn.maparg("<Plug>(gh-pr-review-refresh)", "n") ~= "", "Missing <Plug>(gh-pr-review-refresh)"); assert(prefetch.enabled == true, "Missing diff_view.prefetch.enabled"); assert(prefetch.concurrency == 2, "Missing diff_view.prefetch.concurrency"); assert(prefetch.text_extensions[1] == "lua" and prefetch.text_extensions[2] == "md", "Missing diff_view.prefetch.text_extensions"); assert(comments_panel.position == "bottom", "Missing diff_view.comments_panel.position default"); assert(non_text.enabled == true, "Missing diff_view.non_text.enabled"); assert(non_text.auto_preview == true, "Missing diff_view.non_text.auto_preview"); assert(non_text.show_metadata == true, "Missing diff_view.non_text.show_metadata"); assert(type(virtual_files.classify_file) == "function", "Missing virtual_files.classify_file"); assert(virtual_files.classify_file({ path = "a.png", patch = "" }) == "image", "Expected image classification"); assert(virtual_files.classify_file({ path = "a.zip", patch = "" }) == "asset", "Expected asset classification"); assert(virtual_files.classify_file({ path = "a.lua", patch = "" }) == "text", "Expected text classification"); assert(type(actions.run_non_text_default_action) == "function", "Missing actions.run_non_text_default_action"); assert(type(actions.open_non_text_actions_menu) == "function", "Missing actions.open_non_text_actions_menu"); assert(type(actions.run_non_text_action_at_cursor) == "function", "Missing actions.run_non_text_action_at_cursor"); assert(type(actions.open_security_alert_location) == "function", "Missing actions.open_security_alert_location"); assert(type(pr_service.reply_to_review_thread) == "function", "Missing pr_service.reply_to_review_thread"); assert(type(pr_service.resolve_review_thread) == "function", "Missing pr_service.resolve_review_thread"); assert(type(pr_service.unresolve_review_thread) == "function", "Missing pr_service.unresolve_review_thread"); assert(type(pr_service.update_review_comment) == "function", "Missing pr_service.update_review_comment"); assert(type(pr_service.delete_review_comment) == "function", "Missing pr_service.delete_review_comment"); assert(type(pr_service.set_review_comment_reaction) == "function", "Missing pr_service.set_review_comment_reaction"); assert(type(pr_service.fetch_review_threads_with_pending) == "function", "Missing pr_service.fetch_review_threads_with_pending"); assert(type(pr_service.fetch_review_threads_with_pending_async) == "function", "Missing pr_service.fetch_review_threads_with_pending_async"); assert(type(pr_service.fetch_viewed_files) == "function", "Missing pr_service.fetch_viewed_files"); assert(type(pr_service.fetch_viewed_files_async) == "function", "Missing pr_service.fetch_viewed_files_async"); assert(type(pr_service.set_files_viewed) == "function", "Missing pr_service.set_files_viewed"); assert(type(pr_service.fetch_check_annotations) == "function", "Missing pr_service.fetch_check_annotations"); assert(type(pr_service.fetch_check_annotations_async) == "function", "Missing pr_service.fetch_check_annotations_async"); assert(type(pr_service.fetch_code_scanning_alerts) == "function", "Missing pr_service.fetch_code_scanning_alerts"); assert(type(pr_service.fetch_code_scanning_alerts_async) == "function", "Missing pr_service.fetch_code_scanning_alerts_async"); assert(type(pr_service.fetch_dependency_review) == "function", "Missing pr_service.fetch_dependency_review"); assert(type(pr_service.fetch_dependency_review_async) == "function", "Missing pr_service.fetch_dependency_review_async"); assert(ok_annotations == true, "Missing gh-pr.check_annotations module"); assert(ok_security_annotations == true, "Missing gh-pr.security_annotations module"); assert(ok_security_section == true, "Missing gh-pr.neotree.review_sections.security module"); local ok, health = pcall(require, "gh-pr.health"); assert(ok and type(health.check) == "function", "Missing gh-pr health check entrypoint")',
  '+lua local cfg = require("gh-pr.config").get(); local actions = require("gh-pr.actions"); local url_open = require("gh-pr.url_open"); local helpers = actions._open_target_helpers or {}; assert(((cfg.overview or {}).markdown or {}).link_preview_open_local == "disabled", "Missing secure overview.markdown.link_preview_open_local default"); assert((((cfg.diff_view or {}).images or {}).fallback_open_local) == "disabled", "Missing secure diff_view.images.fallback_open_local default"); assert(type(helpers.normalize_local_open_policy) == "function" and helpers.normalize_local_open_policy("reveal_only", "disabled") == "reveal_only", "Missing local-open policy sanitizer"); assert(type(helpers.effective_local_open_policy) == "function" and helpers.effective_local_open_policy("system", "dangerous.cmd") == "reveal_only", "Dangerous local extensions must downgrade to reveal_only"); assert(type(helpers.resolve_attachment_filename) == "function" and helpers.resolve_attachment_filename("https://objects.githubusercontent.com/?download=1", "evil.cmd", { md = true }) == "attachment.bin", "Attachment filename fallback must not trust dangerous labels"); local ok_url, ok_err = url_open._normalize_url("https://example.com/path"); assert(ok_url == "https://example.com/path" and ok_err == nil, "normalize_url should keep valid https URLs"); local _, scheme_err = url_open._normalize_url("file:///tmp/test"); assert(type(scheme_err) == "string" and scheme_err:find("Only http/https", 1, true) ~= nil, "normalize_url should reject file://"); local _, whitespace_err = url_open._normalize_url("https://example.com/a b"); assert(type(whitespace_err) == "string" and whitespace_err:find("unsupported whitespace", 1, true) ~= nil, "normalize_url should reject whitespace")',
  '+lua local popup = require("gh-pr.comment_popup"); local comment_thread_actions = require("gh-pr.comment_thread_actions"); local origin = vim.api.nvim_get_current_buf(); local ctx = { thread_id = "t1", path = "lua/gh-pr/comment_popup.lua", line = 12 }; local items = { { id = "c1", author = "user", body = "own published", meta = { thread_id = "t1", viewer_did_author = true, comment_is_pending = false, reaction_groups = {} } }, { id = "c2", author = "other", body = "other pending", meta = { thread_id = "t1", viewer_did_author = false, comment_is_pending = true, thread_is_resolved = true, reaction_groups = {} } } }; local ok = select(1, popup.open({ origin_bufnr = origin, tag = "thread", title = "Smoke", items = items, actions = comment_thread_actions.build_popup_actions(ctx), footer_provider = comment_thread_actions.build_popup_footer_provider(ctx), enter = true, position = "editor" })); assert(ok == true, "Comment popup should open"); local popup_buf = vim.api.nvim_get_current_buf(); local popup_win = vim.api.nvim_get_current_win(); assert(vim.b[popup_buf].gh_pr_popup_line_items[vim.api.nvim_win_get_cursor(popup_win)[1]] == 1, "Comment popup should start on first comment"); local lines = vim.api.nvim_buf_get_lines(popup_buf, 0, -1, false); assert(lines[#lines] == "r reply  R quote  x resolve  e edit  D delete  +/- reactions  q close", "Own published comment should show all contextual actions"); assert(vim.fn.maparg("r", "n", false, true).desc == "Reply to selected PR thread", "Missing popup reply mapping"); assert(vim.fn.maparg("R", "n", false, true).desc == "Quote-reply to selected PR thread", "Missing popup quote mapping"); assert(vim.fn.maparg("x", "n", false, true).desc == "Resolve or unresolve selected PR thread", "Missing popup resolve mapping"); assert(vim.fn.maparg("e", "n", false, true).desc == "Edit selected PR comment", "Missing popup edit mapping"); assert(vim.fn.maparg("D", "n", false, true).desc == "Delete selected PR comment", "Missing popup delete mapping"); assert(vim.fn.maparg("+", "n", false, true).desc == "Add reaction to selected PR comment", "Missing popup reaction-add mapping"); assert(vim.fn.maparg("-", "n", false, true).desc == "Remove reaction from selected PR comment", "Missing popup reaction-remove mapping"); local other_line = vim.fn.search("@other", "nw"); assert(other_line > 0, "Other comment line should exist"); vim.api.nvim_win_set_cursor(popup_win, { other_line, 0 }); vim.api.nvim_exec_autocmds("CursorMoved", { buffer = popup_buf, modeline = false }); lines = vim.api.nvim_buf_get_lines(popup_buf, 0, -1, false); assert(lines[#lines] == "r reply  R quote  x unresolve  q close", "Other pending comment should hide owner-only actions and reactions"); popup.close_for_origin(origin, "thread"); local footer = comment_thread_actions.build_popup_footer_provider({ thread_id = "t1" }); lines = footer({ id = "c3", author = "user", body = "own pending", meta = { thread_id = "t1", viewer_did_author = true, comment_is_pending = true } }, {}); assert(type(lines) == "table" and lines[1] == "r reply  R quote  x resolve  e edit  q close", "Own pending comment should hide delete and reactions while keeping edit")',
  '+lua local cfg = require("gh-pr.config").get(); local reactions_cfg = (cfg.line_comments or {}).reactions or {}; local picker_cfg = reactions_cfg.picker or {}; local reactions = require("gh-pr.reactions"); local picker = require("gh-pr.ui.reaction_picker"); local summary = reactions.render_summary({ { content = "THUMBS_UP", total_count = 2, viewer_has_reacted = true }, { content = "HEART", total_count = 1, viewer_has_reacted = false } }, { render = reactions_cfg.render, viewer_marker = reactions_cfg.viewer_marker }); assert(reactions_cfg.render == "emoji", "Missing line_comments.reactions.render default"); assert(reactions_cfg.viewer_marker == "*", "Missing line_comments.reactions.viewer_marker default"); assert(picker_cfg.position == "cursor", "Missing line_comments.reactions.picker.position default"); assert(picker_cfg.width == 56, "Missing line_comments.reactions.picker.width default"); assert(picker_cfg.height == 10, "Missing line_comments.reactions.picker.height default"); assert(summary:find("👍", 1, true) ~= nil and summary:find("THUMBS_UP", 1, true) == nil, "Reaction summary should render emoji labels"); local sections = reactions.build_picker_sections({ { content = "THUMBS_UP", total_count = 2, viewer_has_reacted = true }, { content = "ROCKET", total_count = 1, viewer_has_reacted = true } }, { viewer_marker = "*" }); assert(type(sections) == "table" and sections[1] and sections[1].items[1] and sections[1].items[1].content == "THUMBS_UP", "Reaction sections should start with quick reactions"); local origin = vim.api.nvim_get_current_buf(); local selected = nil; local open_ok, handle = picker.open({ origin_bufnr = origin, anchor_win = vim.api.nvim_get_current_win(), mode = "add", reaction_groups = { { content = "THUMBS_UP", total_count = 2, viewer_has_reacted = true }, { content = "ROCKET", total_count = 1, viewer_has_reacted = true } }, on_select = function(item) selected = item.content end }); assert(open_ok == true and type(handle) == "table", "Reaction picker should open"); assert((picker.current_item(handle.bufnr) or {}).content == "THUMBS_UP", "Reaction picker should start on thumbs up"); assert(picker.move(handle.bufnr, "right") == true, "Reaction picker should move right"); assert((picker.current_item(handle.bufnr) or {}).content == "HEART", "Reaction picker should move across quick reactions"); assert(picker.move(handle.bufnr, "down") == true, "Reaction picker should move down"); assert((picker.current_item(handle.bufnr) or {}).content == "EYES", "Reaction picker should move into matching more-reactions column"); assert(picker.confirm(handle.bufnr) == true and selected == "EYES", "Reaction picker should confirm selected reaction"); local remove_selected = nil; local remove_ok, remove_handle = picker.open({ origin_bufnr = origin, anchor_win = vim.api.nvim_get_current_win(), mode = "remove", reaction_groups = { { content = "ROCKET", total_count = 3, viewer_has_reacted = true } }, on_select = function(item) remove_selected = item.content end }); assert(remove_ok == true and type(remove_handle) == "table", "Reaction picker remove mode should open"); assert((picker.current_item(remove_handle.bufnr) or {}).content == "ROCKET", "Reaction picker remove mode should keep reacted item"); assert(picker.confirm(remove_handle.bufnr) == true and remove_selected == "ROCKET", "Reaction picker remove mode should confirm current reaction"); local none_ok, none_err = picker.open({ origin_bufnr = origin, mode = "remove", reaction_groups = {}, on_select = function() end }); assert(none_ok == false and none_err == "You do not have any reactions on this comment", "Reaction picker should reject empty remove mode")',
  '+lua local pr_service = require("gh-pr.pr_service"); local gh = require("gh-pr.gh"); local original_run = gh.run; local original_run_json = gh.run_json; local original_resolve = pr_service.resolve_repository; local rest_args = nil; gh.run = function(args) rest_args = vim.deepcopy(args); return "", nil end; pr_service.resolve_repository = function() return { owner = "Middle-Sea", name = "MSBA-MSBA-test", full_name = "Middle-Sea/MSBA-MSBA-test" }, nil end; local ok, err = pr_service.delete_review_comment({ comment_id = "gid://review-comment", comment_database_id = 2892208391 }); assert(ok == true and err == nil, "Delete review comment should use REST when database_id is present"); assert(rest_args and rest_args[1] == "api" and rest_args[2] == "-X" and rest_args[3] == "DELETE" and rest_args[4] == "repos/Middle-Sea/MSBA-MSBA-test/pulls/comments/2892208391", "Delete review comment should target the pull comment REST endpoint"); local gql_args = nil; gh.run_json = function(args) gql_args = vim.deepcopy(args); return { data = { deletePullRequestReviewComment = { pullRequestReviewComment = { id = "gid://review-comment" } } } }, nil end; ok, err = pr_service.delete_review_comment("gid://review-comment"); assert(ok == true and err == nil, "Delete review comment should keep GraphQL fallback"); assert(type(gql_args) == "table" and table.concat(gql_args, " "):find("deletePullRequestReviewComment", 1, true) ~= nil, "Delete review comment fallback should call the GraphQL mutation"); gh.run = original_run; gh.run_json = original_run_json; pr_service.resolve_repository = original_resolve; local drafts = require("gh-pr.neotree.review_sections.drafts"); local nodes = drafts.build_nodes({ number = 42 }, { pending_review_loaded = true, pending_review_comments = { { id = "c1", thread_id = "t1", path = "lua/gh-pr/actions.lua", thread_path = "lua/gh-pr/actions.lua", line = 10, original_line = 10, thread_line = 10, thread_original_line = 10, body = "draft body", author = "reviewer", created_at = "2026-03-07T00:00:00Z", state = "PENDING" } } }); assert(type(nodes) == "table" and nodes[1] and nodes[1].type == "comment_file", "Drafts section should group by file"); assert(type(nodes[1].children) == "table" and nodes[1].children[1] and nodes[1].children[1].extra.kind == "comment_thread", "Drafts section should group by thread"); assert(type(nodes[1].children[1].children) == "table" and nodes[1].children[1].children[1] and nodes[1].children[1].children[1].extra.kind == "comment_thread_item", "Drafts section should expose draft comments as navigable items"); local actions = require("gh-pr.actions"); local called; local original = actions.open_thread_comment_evolution_diff; actions.open_thread_comment_evolution_diff = function(payload, opts) called = { payload = payload, opts = opts }; return true end; actions.open_overview_thread_workspace({ pr_number = 123, path = "lua/gh-pr/actions.lua", comment_commit_oid = "abc" }, { new_tab = false }); assert(called and called.payload and called.payload.path == "lua/gh-pr/actions.lua", "Overview thread action must delegate to evolution diff"); actions.open_thread_comment_evolution_diff = original'
)

if ($WithHelpTags) {
  $nvimArgs += '+helptags doc'
}

$nvimArgs += '+qa'

& nvim @nvimArgs
if ($LASTEXITCODE -ne 0) {
  throw "Headless smoke failed with exit code $LASTEXITCODE."
}

Write-Host "Headless smoke passed." -ForegroundColor Green
